def main() -> None:
    parser = argparse.ArgumentParser(description="Unpack Project-IMPJR v4.1 files, rebuild Kaggle bundle, and git push.")
    parser.add_argument("--repo-root", default=".", help="Path to your local GitHub repository root")
    parser.add_argument("--push", action="store_true", help="Automatically run git add, git commit, and git push")
    parser.add_argument("--branch", default=None, help="Optional git branch name to push to")
    args = parser.parse_args()

    root = Path(args.repo_root).resolve()
    if not (root / "feature engineering scripts").exists():
        print(f"ERROR: Could not find 'feature engineering scripts' inside {root}. Run this script from your repo root.")
        sys.exit(1)

    raw_zip = base64.b64decode(PAYLOAD_B64)
    with zipfile.ZipFile(io.BytesIO(raw_zip)) as zf:
        for member in zf.namelist():
            dest = root / member
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_bytes(zf.read(member))
            print(f"[v4.1] Installed {member}")

    fe_dir = root / "feature engineering scripts"
    build_script = fe_dir / "orchestration" / "kaggle_relay" / "build_bundle.py"
    if build_script.exists():
        subprocess.run([sys.executable, str(build_script)], cwd=str(fe_dir), check=True)

    if args.push:
        print("\n[git] Staging Project-IMPJR v4.1 files...")
        subprocess.run(["git", "add", "new_plan.md", "feature engineering scripts/"], cwd=str(root), check=True)
        commit_msg = "Upgrade to Project-IMPJR v4.1 Supervised Multi-Horizon Stacker, O(log L) Mamba Scan & Direct GPU Inference"
        subprocess.run(["git", "commit", "-m", commit_msg], cwd=str(root), check=False)
        push_cmd = ["git", "push"] + (["origin", args.branch] if args.branch else [])
        subprocess.run(push_cmd, cwd=str(root), check=True)
        print("[git] Successfully pushed Project-IMPJR v4.1 to GitHub!")
    else:
        print("\nAll v4.1 files unpacked and Kaggle bundle rebuilt! Run with --push to commit and push to GitHub.")

if __name__ == "__main__":
    main()
